  tm_subtitle: {
    en: 'Resolve any written form of an Ayurvedic botanical — script native name, IAST transliteration, regional synonym or binomial — to one canonical entity key used by the passport and retrieval index.',
    hi: 'किसी भी आयुर्वेदिक वनस्पति के किसी भी लिखित रूप — मूल लिपि नाम, IAST लिप्यंतरण, क्षेत्रीय पर्यायवाची या द्विनाम — को पासपोर्ट और पुनर्प्राप्ति सूचकांक द्वारा उपयोग की जाने वाली एक विहित इकाई कुंजी में समाधान करें।',
    mr: 'कोणत्याही आयुर्वेदिक वनस्पतीचे कोणतेही लिखित स्वरूप — मूळ लिपी नाव, IAST लिप्यंतर, प्रादेशिक समानार्थी किंवा द्विनाम — पासपोर्ट व पुनर्प्राप्ती निर्देशांकाने वापरल्या जाणाऱ्या एका विहित घटक-कळीत निराकरण करा.',
    ta: 'ஒரு ஆயுர்வேத தாவரத்தின் எந்த எழுத்து வடிவையும் — மூல எழுத்துப் பெயர், IAST பெயர்ப்பெயர்ப்பு, பிராந்திய இணைச்சொல் அல்லது இருவழிப் பெயர் — பாஸ்போர்ட் மற்றும் மீட்பு அகரவரிசையால் பயன்படுத்தப்படும் ஒரே நியம அலகு விசையாகத் தீர்மானியுங்கள்.',
    te: 'ఏ ఆయుర్వేద మొక్క యొక్క ఏ రాత రూపాన్నైనా — మూల లిపి పేరు, IAST లిప్యంతరణ, ప్రాంతీయ పర్యాయపదం లేదా ద్వినామం — పాస్‌పోర్ట్ మరియు రిట్రీవల్ ఇండెక్స్ ఉపయోగించే ఒకే విహిత ఘటక కీగా పరిష్కరించండి.',
    kn: 'ಯಾವುದೇ ಆಯುರ್ವೇದ ಸಸ್ಯದ ಯಾವುದೇ ಬರಹ ರೂಪವನ್ನೂ — ಮೂಲ ಲಿಪಿ ಹೆಸರು, IAST ಲಿಪ್ಯಂತರಣ, ಪ್ರಾದೇಶಿಕ ಸಮಾನಾರ್ಥಕ ಅಥವಾ ದ್ವಿನಾಮ — ಪಾಸ್‌ಪೋರ್ಟ್ ಮತ್ತು ಮರುಪ್ರಾಪ್ತಿ ಸೂಚಿಗಳು ಬಳಸುವ ಒಂದೇ ವಿಹಿತ ಘಟಕ ಕೀಲಿಗೆ ಪರಿಹರಿಸಿ.',
    bn: 'যেকোনো আয়ুর্বেদীয় উদ্ভিদের যেকোনো লিখিত রূপ — মূল লিপি নাম, IAST প্রতিবর্ণীকরণ, আঞ্চলিক সমার্থক বা দ্বিপদ নাম — পাসপোর্ট ও পুনরুদ্ধার সূচক ব্যবহার করে এমন একটি অনুমোদিত সত্ত্বা কী-তে সমাধান করুন।',
    gu: 'કોઈપણ આયુર્વેદિક વનસ્પતિના કોઈપણ લેખિત સ્વરૂપને — મૂળ લિપિ નામ, IAST લિપ્યંતરણ, પ્રાદેશિક સમાનાર્થી કે દ્વિનામ — પાસપોર્ટ અને પુનઃપ્રાપ્તિ અનુક્રમણ વાપરે તેવી એક વિહિત એન્ટિટી કીમાં ઉકેલો.',
    ml: 'ഏതൊരു ആയുർവേദ സസ്യത്തിന്റെയും ഏതെങ്കിലും എഴുത്തുരൂപം — മൂല ലിപി പേര്, IAST ലിപ്യന്തരണം, പ്രാദേശിക പര്യായം അല്ലെങ്കിൽ ദ്വിനാമം — പാസ്‌പോർട്ടും വീണ്ടെടുപ്പ് സൂചികയും ഉപയോഗിക്കുന്ന ഒരൊറ്റ അധികൃത എന്റിറ്റി കീയിലേക്ക് പരിഹരിക്കുക.',
    sa: 'कस्याश्चित् आयुर्वेदवनस्पतेः किमपि लिखितरूपं — मूललिपिनाम, IAST-लिप्यन्तरणं, प्रादेशिकपर्यायः वा द्विनाम — पासपोर्ट-पुनःप्राप्ति-सूचिकया उपयुज्यमानायाम् एकस्यां विहितायां वस्तुकुञ्जिकायां परिहरतु।',
  },
