    kn: 'D&C ಕಾಯ್ದೆ ಮತ್ತು FSSAI ಯೋಜನೆಗಳಲ್ಲಿ ಔಷಧವನ್ನು ಆಹಾರ ಅಥವಾ ಸೌಂದರ್ಯ ಸಾಧನದಿಂದ ಬೇರ್ಪಡಿಸುವುದು ಚಿಕಿತ್ಸಾತ್ಮಕ ಪದಬಳಕೆ.',
    bn: 'D&C আইন ও FSSAI প্রকল্পে ঔষধকে খাদ্য বা প্রসাধন থেকে আলাদা করে নিরাময়মূলক ভাষা।',
    gu: 'D&C અધિનિયમ અને FSSAI યોજનાઓમાં ઔષધને આહાર કે સૌંદર્ય પ્રસાધનથી અલગ પાડતી બાબત ઉપચારાત્મક શબ્દાવલી છે.',
    ml: 'D&C ആക്ടിലും FSSAI പദ്ധതികളിലും മരുന്നിനെ ഭക്ഷണത്തിൽ നിന്നോ സൗന്ദര്യവർധകത്തിൽ നിന്നോ വേർതിരിക്കുന്നത് ചികിത്സാപരമായ പദപ്രയോഗമാണ്.',
