  pc_w4_help: {
    en: 'Classical processing keeps a formulation inside the traditional frame; advanced extraction can push it toward a Phytopharmaceutical.',
    hi: 'शास्त्रीय प्रसंस्करण फॉर्मूलेशन को पारंपरिक ढाँचे में रखता है; उन्नत निष्कर्षण इसे फाइटोफार्मास्यूटिकल की ओर ले जा सकता है।',
    mr: 'शास्त्रीय प्रक्रिया फॉर्म्युलेशन पारंपरिक चौकटीत ठेवते; प्रगत निष्कर्षण ते फायटोफार्मास्युटिकलकडे नेऊ शकते.',
    ta: 'செவ்வியல் செயலாக்கம் கலவையை பாரம்பரிய சட்டகத்தில் வைக்கிறது; மேம்பட்ட பிரித்தெடுத்தல் அதை தாவர மருந்தியல் நோக்கி தள்ளலாம்.',
    te: 'శాస్త్రీయ ప్రక్రియ ఫార్ములేషన్‌ను సాంప్రదాయ చట్రంలో ఉంచుతుంది; అధునాతన సారం తీయడం దానిని ఫైటోఫార్మాస్యూటికల్ వైపు నెట్టవచ్చు.',
    kn: 'ಶಾಸ್ತ್ರೀಯ ಸಂಸ್ಕರಣೆ ಸೂತ್ರೀಕರಣವನ್ನು ಸಾಂಪ್ರದಾಯಿಕ ಚೌಕಟ್ಟಿನಲ್ಲಿ ಇಡುತ್ತದೆ; ಸುಧಾರಿತ ಸಾರತೆಗೆತ ಅದನ್ನು ಫೈಟೋಫಾರ್ಮಾಸ್ಯುಟಿಕಲ್ ಕಡೆಗೆ ತಳ್ಳಬಹುದು.',
    bn: 'শাস্ত্রীয় প্রক্রিয়াকরণ ফর্মুলেশনকে ঐতিহ্যবাহী কাঠামোয় রাখে; উন্নত নিষ্কাশন এটিকে ফাইটোফার্মাসিউটিক্যালের দিকে ঠেলে দিতে পারে।',
    gu: 'શાસ્ત્રીય પ્રક્રિયા ફોર્મ્યુલેશનને પરંપરાગત ચોકઠામાં રાખે છે; અદ્યતન નિષ્કર્ષણ તેને ફાયટોફાર્માસ્યુટિકલ તરફ ધકેલી શકે છે.',
    ml: 'ശാസ്ത്രീയ സംസ്കരണം ഫോർമുലേഷനെ പാരമ്പര്യ ചട്ടക്കൂട്ടിൽ നിർത്തുന്നു; നവീന വേർതിരിച്ചെടുക്കൽ അതിനെ ഫൈറ്റോഫാർമസ്യൂട്ടിക്കലിലേക്ക് തള്ളിയിടാം.',
    sa: 'शास्त्रीयसंस्करणं योगं पारम्परिक-चौकट्याम् रक्षति; प्रगत-निष्कर्षणं तं फाइटोफार्मास्युटिकल्-दिशि नुदति।',
  },
