  pa_calc_desc: {
    en: 'Deterministic output of {engines} — Patent Search (prior art), Ingredient & Novelty analysis, Section 3(p) check, Disclosure Sentinel, Evidence-to-Claim matrix, Ownership audit, FTO scan and Documentation completeness. No random scores.',
    hi: '{engines} का निर्धारित परिणाम — पेटेंट खोज (पूर्व कला), संघटक एवं नवता विश्लेषण, धारा 3(p) जाँच, प्रकटीकरण सेंटिनल, साक्ष्य-दावा मैट्रिक्स, स्वामित्व ऑडिट, FTO स्कैन एवं दस्तावेज़ीकरण पूर्णता। कोई अ-random स्कोर नहीं।',
    mr: '{engines} चे निश्चित output — पेटंट शोध (पूर्व कला), घटक व नवता विश्लेषण, धारा 3(p) तपासणी, उघडपण सेंटिनेल, साक्ष-दावा मॅट्रिक्स, मालकी ऑडिट, FTO स्कॅन आणि दस्तऐवजीकरण पूर्णता. कोणतेही अ-random स्कोर नाही.',
    ta: '{engines} இன் நிண்ணிய விளைவு — காப்புரிமை தேடல் (முந்தைய கலை), கூற்று மற்றும் புதுமை பகுப்பாய்வு, பிரிவு 3(p) சரிபார்ப்பு, வெளியீடு காவல், சான்று-உரிமை அணி, உரிமையாளர் தணிவீடு, FTO ஆய்வு மற்றும் ஆவண நிறைவு. சீரற்ற மதிப்பெண்கள் இல்லை.',
    te: '{engines} నుండి నిర్ణీత ఫలితం — పేటెంట్ శోధన (ప్రియర్ ఆర్ట్), సాధకాలు & నూతనత విశ్లేషణ, సెక్షన్ 3(p) తనిఖీ, ప్రకటన సెంటినెల్, సాక్ష్య-దావన్ మాతృకం, యాజమాన్య ఆడిట్, FTO స్కాన్ మరియు పత్రాల పూర్తత. యాదృచ్ఛిక స్కోరులు లేవు.',
    kn: '{engines} ನಿಂದ ನಿರ್ಧಾರಿತ ಫಲಿತಾಂಶ — ಪೇಟೆಂಟ್ ಹುಡುಕಾಟ (ಪೂರ್ವ-ಕಲಾ), ಸಾಧಕ ಮತ್ತು ನವತೆ ವಿಶ್ಲೇಷಣೆ, ವಿಭಾಗ 3(p) ಪರಿಶೀಲನೆ, ಬಹಿರಂಗಪಡಿಸುವಿಕೆ ಸೆನ್ಟಿನಲ್, ಸಾಕ್ಷ್ಯ-ಹಕ್ಕು ಮ್ಯಾಟ್ರಿಕ್ಸ್, ಮಾಲೀಕತೆ ಪರಿಶೀಲನೆ, FTO ಪರಿಶೀಲನೆ ಮತ್ತು ದಾಖಲೆ ಪೂರ್ಣತೆ. ಯಾದೃಚ್ಛಿಕ ಅಂಕಗಳಿಲ್ಲ.',
    bn: '{engines}-এর নির্ধারিত ফলাফল — পেটেন্ট অনুসন্ধান (আগের শিল্প), উপাদান ও নবতা বিশ্লেষণ, ধারা 3(p) যাচাই, প্রকাশ সেন্টিনেল, প্রমাণ-দাবি ম্যাট্রিক্স, মালিকানা নিরীক্ষা, FTO স্ক্যান এবং নথি সম্পূর্ণতা। কোনো এলোমেলো স্কোর নেই।',
    gu: '{engines} નું નિર્ધારિત પરિણામ — પેટન્ટ શોધ (અગાઉનો કલા), ઘટક અને નવીનતા વિશ્લેષણ, કલમ 3(p) તપાસ, જાહેરાત સેન્ટિનેલ, સાક્ષ્ય-દાવા મેટ્રિક્સ, માલિકી ઓડિટ, FTO સ્કેન અને દસ્તાવેજ પૂર્ણતા. કોઈ અનિયમિત સ્કોર નથી.',
    ml: '{engines} ന്റെ നിശ്ചിത ഫലം — പേറ്റൻറ് തിരയൽ (പുർവ് കല), ഘടകവും പുതിയതരുമായ വിശകലനം, വിഭാഗം 3(p) പരിശോധന, പ്രസിദ്ധീകരണ സെന്റിനൽ, തെളിവ്-അവകാശവാദം മാട്രിക്സ്, ഉടമാധികാര ഓഡിറ്റ്, FTO സ്കാൻ, രേഖപ്പെടുത്തൽ പൂർണ്ണത. അനിശ്ചിത സ്കോറുകളില്ല.',
    sa: '{engines} इति निश्चित-फलम् — पेटेन्ट्-अन्वेषणम् (पूर्व-कला), साधक-नवता-विश्लेषणम्, धारा ३(p)-परीक्षणम्, उद्धाटन-सेन्टिनेल्, प्रमाण-दावा-जालकम्, स्वामित्व-परीक्षणम्, FTO-परीक्षणम् च दस्तावेज-पूर्णता। यादृच्छिक-अङ्काः न सन्ति।',
  },
