  rd_tip_body: {
    en: 'Roadmap phases reflect standard Ayurveda/IP filing flows. Re-run each intelligence engine on this passport to close gaps before the Evidence Collection and Compliance Submission phases.',
    hi: 'रोडमैप चरण मानक आयुर्वेद/आईपी दाखिला प्रवाह दर्शाते हैं। साक्ष्य संग्रह एवं अनुपालन प्रस्तुति चरणों से पूर्व अंतराल समाप्त करने हेतु इस पासपोर्ट पर प्रत्येक इंटेलिजेंस इंजन पुनः चलाएं।',
    mr: 'रोडमॅप टप्पे प्रमाणित आयुर्वेद/आयपी दाखल प्रवाह दर्शवतात. साक्ष संग्रह आणि पूर्तता सादरीकरण या टप्प्यांपूर्वी अंतरे भरून काढण्यासाठी या पासपोर्टवर प्रत्येक इंटेलिजन्स इंजिन पुन्हा चालवा.',
    ta: 'சாலை வரைபட நிலைகள் நியம வழக்கமான ஆயுர்வேத/IP கோப்பிடல் பாதைகளைக் குறிக்கின்றன. சான்று சேகரிப்பு மற்றும் இணக்கச் சமர்ப்பி நிலைகளுக்கு முன் இடைவெளிகளை நிரப்ப இந்த பாஸ்போர்டில் ஒவ்வொரு அறிவு இயந்திரத்தையும் மீண்டும் இயக்கவும்.',
    te: 'రోడ్‌మ్యాప్ దశలు ప్రామాణిక ఆయుర్వేద/IP దాఖల ప్రవాహాలను సూచిస్తాయి. సాక్ష్య సేకరణ మరియు సంపూర్ణతా సమర్పణ దశల ముందు లోటులు పూడించడానికి ఈ పాస్‌పోర్ట్‌పై ప్రతి ఇంటెలిజెన్స్ ఇంజిన్‌ను మళ్ళీ నడపండి.',
    kn: 'ರೋಡ್‌ಮ್ಯಾಪ್ ಹಂತಗಳು ಪ್ರಮಾಣಿಕ ಆಯುರ್ವೇದ/IP ದಾಖಲ ಹರಿವುಗಳನ್ನು ಪ್ರತಿಫಲಿಸುತ್ತವೆ. ಸಾಕ್ಷ್ಯ ಸಂಗ್ರಹ ಮತ್ತು ಅನುಸರಣೆ ಸಲ್ಲಿಗೆ ಮೊದಲು ಅಂತರ ತುಂಬಲು ಈ ಪಾಸ್‌ಪೋರ್ಟ್‌ನಲ್ಲಿ ಪ್ರತಿ ಇಂಟೆಲಿಜೆನ್ಸ್ ಎಂಜಿನ್ ಅನ್ನು ಮತ್ತೆ ಓಡಿಸಿ.',
    bn: 'রোডম্যাপ পর্বগুলি প্রচলিত আয়ুর্বেদ/IP দাখিল প্রবাহ প্রতিফলিত করে। প্রমাণ সংগ্রহ ও সম্মতি জমা দেওয়ার পর্বের আগে ফাঁক পূরণ করতে এই পাসপোর্টে প্রতিটি ইন্টেলিজেন্স ইঞ্জিন পুনরায় চালান।',
    gu: 'રોડમેપ તબક્કાઓ પ્રમાણિક આયુર્વેદ/IP ફાઇલિંગ પ્રવાહોને દર્શાવે છે. પુરાવા સંગ્રહ અને અનુપાલન સબમિશન તબક્કાઓ પહેલાં ખાલી જગ્યા ભરવા આ પાસપોર્ટ પર દરેક ઇન્ટેલિજન્સ એન્જિન ફરી ચલાવો.',
    ml: 'റോഡ്മാപ്പ് ഘട്ടങ്ങൾ സ്റ്റാൻഡേർഡ് ആയുർവേദ/IP ഫയൽ ഫ്ലോകൾ പ്രതിഫലിപ്പിക്കുന്നു. തെളിവ് ശേഖപ്പെടുത്തൽ, കംപ്ലയൻസ് സമർപ്പണം ഘട്ടങ്ങൾക്ക് മുമ്പ് സമുദ്രങ്ങൾ നിറയ്ക്കാൻ ഈ പാസ്‌പോർട്ടിൽ ഓരോ ഇന്റലിജൻസ് എഞ്ചിനും വീണ്ടും ഓടിക്കുക.',
    sa: 'मार्गपट-अवस्थाः आयुर्वेद/IP निवेदन-प्रवाहान् प्रतिफलयन्ति। प्रमाण-संग्रह-अनुपालन-समर्पण-अवस्थाभ्यः पूर्वं रिक्तानि पुरयितुं पासपोर्टे प्रत्येकं बुद्धि-यन्त्रं पुनः प्रसारयतु।',
  },
