  da_subtitle: {
    en: 'Upload Certificates of Analysis (COA), lab assays, or label PDFs. The sandboxed OCR extractor isolates typed factual parameters and sanitizes adversarial prompt-injections before model reasoning.',
    hi: 'विश्लेषण प्रमाणपत्र (COA), प्रयोगशाला परीक्षण या लेबल PDF अपलोड करें। सैंडबॉक्स OCR निष्कर्षक टाइप किए गए तथ्यात्मक मानदंडों को अलग करता है और मॉडल तर्क से पूर्व प्रतिकूल प्रॉम्प्ट-इंजेक्शन को साफ करता है।',
    mr: 'विश्लेषण प्रमाणपत्रे (COA), प्रयोगशाळा चाचण्या किंवा लेबल PDF अपलोड करा. सँडबॉक्स OCR निष्कर्शक टाइप केलेली तथ्यात्मक निकषे वेगळे करते आणि प्रतिकूल प्रॉम्प्ट-इंजेक्शन क्लीन करते.',
    ta: 'ஆய்வு சான்றித்துறைகள் (COA), ஆய்வகைச் சோதனைகள் அல்லது லேபிள் PDF ஆகியவற்றைப் பதிவேற்றுங்கள். சாண்ட்பாக்ஸ் OCR பிரிப்பான் பதிவான தகவல் அளவுகோல்களைத் தனிப்படுத்தி, மாதிரி சிந்தனைக்கு முன் எதிர்க்காலி ப்ராம்ப்ட்-இன்ஜெக்ஷன்களை சுத்தம் செய்கிறது.',
    te: 'విశ్లేషణ సర్టిఫికెట్లు (COA), ల్యాబ్ అస్సేలు లేదా లేబుల్ PDF లను అప్‌లోడ్ చేయండి. శాండ్‌బాక్స్ OCR ఎక్స్‌ట్రాక్టర్ టైప్ చేసిన వాస్తవ పరిమాణాలను వేరుచేస్తుంది, మోడల్ ఆలోచనకు ముందు ప్రతికూల ప్రామ్ప్ట్-ఇన్‌జెక్షన్‌లను పరిశుద్ధి చేస్తుంది.',
    kn: 'ವಿಶ್ಲೇಷಣೆ ಪ್ರಮಾಣಪತ್ರಗಳು (COA), ಪ್ರಯೋಗಾಲಯ ಪರೀಕ್ಷೆಗಳು ಅಥವಾ ಲೇಬಲ್ PDF ಗಳನ್ನು ಅಪ್‌ಲೋಡ್ ಮಾಡಿ. ಸ್ಯಾಂಡ್‌ಬಾಕ್ಸ್ OCR ಹರಿಸುವಿಕೆಯು ಟೈಪ್ ಮಾಡಿದ ವಾಸ್ತವಿಕ ನಿಯಮಗಳನ್ನು ಪ್ರತ್ಯೇಕಿಸುತ್ತದೆ ಮತ್ತು ಮಾದರಿ ಚಿಂತನೆಗೆ ಮೊದಲು ಪ್ರತಿಕೂಲ ಪ್ರಾಮ್ಪ್ಟ್-ಇಂಜೆಕ್ಷನ್ ಅನ್ನು ಸ್ವಚ್ಛಗೊಳಿಸುತ್ತದೆ.',
    bn: 'বিশ্লেষণ সার্টিফিকেট (COA), ল্যাব অ্যাসে বা লেবেল PDF আপলোড করুন। স্যান্ডবক্সড OCR এক্সট্রাক্টর টাইপ করা তথ্যমূলক প্যারামিটার আলাদা করে এবং মডেল যুক্তির আগে প্রতিকূল প্রম্পট-ইনজেকশন পরিষ্কার করে।',
    gu: 'વિશ્લેષણ પ્રમાણપત્રો (COA), લેબ એસે અથવા લેબલ PDF અપલોડ કરો. સેન્ડબોક્સ OCR એક્સ્ટ્રેક્ટર ટાઇપ કરેલા તથ્યાત્મક માપદંડો છૂટાં કરે છે અને મોડલ તર્જન પહેલાં પ્રતિકૂલ પ્રોમ્પ્ટ-ઇન્જેક્શન સાફ કરે છે.',
    ml: 'വിശകലന സർട്ടിഫിക്കറ്റുകൾ (COA), ലാബ് അസൈകൾ അല്ലെങ്കിൽ ലേബൽ PDF അപ്‌ലോഡ് ചെയ്യുക. സാൻഡ്ബോക്സ് OCR എക്‌സ്ട്രാക്ടർ ടൈപ്പ് ചെയ്ത വസ്തുതാത്മക പരിമാണങ്ങൾ വേർതിരിക്കുകയാണ്, മോഡൽ ചിന്തനയ്ക്ക് മുമ്പ് വിരുദ്ധമായ പ്രോംപ്റ്റ്-ഇൻജക്ഷൻ സ്വച്ഛം ചെയ്യുന്നു.',
    sa: 'विश्लेषण-प्रमाणपत्राणि (COA), प्रयोगशाला-परीक्षणानि वा लेबल-PDF उत्प्लवतु। सैण्डबक्स्-OCR-निष्कर्शकः टाइपित-वास्तविक-निकषान् पृथक्कृत्य प्रतिकूल-प्रॉम्प्ट-इंजेक्शनं मॉडल-तर्कात् पूर्वं शोधयति।',
  },
