    ta: 'ஒவ்வொரு தாவரத்திற்கும் கோப்பம்: அடையாளம் மற்றும் பெயர்கள், உற்பத்தி, பாதுகாப்பு, ABS, TK மற்றும் IP நிலை — சான்று படிநிலைகளுடன் இணைக்கப்பட்டது.',
    te: 'ప్రతి మొక్కకు గ్రాఫ్: గుర్తింపు & పేర్లు, మూలం, పరిరక్షణ, ABS, TK మరియు IP స్థానం — సాక్ష్య సోపానంతో అనుసంధానితం.',
    kn: 'ಪ್ರತಿ ಸಸ್ಯಕ್ಕೆ ಗ್ರಾಫ್: ಗುರುತಿಸುವಿಕೆ & ಹೆಸರುಗಳು, ಮೂಲ, ಸಂರಕ್ಷಣೆ, ABS, TK ಮತ್ತು IP ಸ್ಥಿತಿ — ಸಾಕ್ಷ್ಯ ಮಡಿಯೊಂದಿಗೆ ಜೋಡಿಸಲಾಗಿದೆ.',
    bn: 'প্রতি উদ্ভিদের গ্রাফ: পরিচয় ও নাম, উৎস, সংরক্ষণ, ABS, TK ও IP অবস্থা — প্রমাণ সিঁড়ির সাথে সংযুক্ত।',
    gu: 'દરેક છોડનો ગ્રાફ: ઓળખ અને નામ, ઉદ્ભવ, સંરક્ષણ, ABS, TK અને IP સ્થિતિ — સાક્ષ્ય સીડી સાથે જોડાયેલ.',
    ml: 'ഓരോ സസ്യവും ഗ്രാഫ്: തിരിച്ചറിയുക & പേരുകൾ, ഉറവിടം, സംരക്ഷണം, ABS, TK, IP നില — തെളിവ് ചരടിയുമായി ബന്ധിപ്പിച്ചിരിക്കുന്നു.',
    sa: 'प्रति-सस्य-ग्राफः अनन्यूप-नामचरित्रं, उत्पत्तिः, सङ्क्षणम्, ABS, TK तथा IP-स्थितिः — प्रमाण-सोपानेन सहितम्।',
