    kn: 'ಮಾರುಕಟ್ಟೆ / ರಫ್ತು ಸಿದ್ಧತಾ ಎಂಜಿನ್ ಚಲಾಯಿಸಲು ಮೊದಲು ಇನ್ನೊವೇಷನ್ ಪಾಸ್‌ಪೋರ್ಟ್ ರಚಿಸಿ.',
    bn: 'মার্কেট / রপ্তানি প্রস্তুতি ইঞ্জিন চালাতে প্রথমে একটি ইনোভেশন পাসপোর্ট তৈরি করুন।',
