    ml: 'മാർക്കറ്റ് / കയറ്റുമതി സജ്ജത എൻജിൻ പ്രവർത്തിപ്പിക്കാൻ ആദ്യം ഒരു ഇന്നൊവേഷൻ പാസ്പോർട്ട് സൃഷ്ടിക്കുക.',
