    bn: 'ডসিয়ার একত্র করা শুরু করতে প্রতিটি অনুপস্থিত ব্যবধান প্রমাণ ম্যাট্রিক্সের সাথে যুক্ত করুন।',
    gu: 'ડોસિયર જોડવાનું શરૂ કરવા દરેક ગુમ ગેપને પુરાવા મેટ્રિક્સ સાથે જોડો.',
    ml: 'ഡോസിയർ കൂട്ടിച്ചേർക്കാൻ തുടങ്ങാൻ ഓരോ അപൂർവ്വ വിടവും തെളിവ് മാട്രിക്സുമായി ജോടിയാക്കുക.',
    sa: 'डोसियरं संयोजयितुं प्रत्येकम् अनुपस्थितम् अन्तरं प्रमाण-मैट्रिक्सेन सह योजयतु।',
