    gu: 'ફીચર ફ્લેગ, AI એજન્ટ એક્ઝિક્યુશન ટેલિમેટ્રી અને DPDP ક્રિપ્ટોગ્રાફિક ઓડિટ ટ્રેલ માટે રિયલ-ટાઇમ કંટ્રોલ પ્લેન.',
    ml: 'ഫീച്ചർ ഫ്ലാഗുകൾ, AI ഏജന്റ് എക്സിക്യുഷൻ ടെലിമെട്രി, DPDP ക്രിപ്റ്റോഗ്രാഫിക് ഓഡിറ്റ് ട്രെയിലുകൾക്കുള്ള റിയൽ-ടൈം കൺട്രോൾ പ്ലെയിൻ.',
