  wi_subtitle: {
    en: 'Mutate promotional claims or formulation parameters live. The reactive dependency DAG recomputes only the affected classifier/rule nodes and highlights the precise compliance diff.',
    hi: 'प्रचार दावों या फॉर्मूलेशन मापदंडों को लाइव बदलें। रिएक्टिव निर्भरता DAG केवल प्रभावित क्लासिफायर/नियम नोड्स की पुनः गणना करता है और सटीक अनुपालन अंतर दिखाता है।',
    mr: 'प्रचार दावे किंवा सूत्रीकरण घटक जिवंत बदला. प्रतिक्रियाशील अवलंबन DAG फक्त बाधित वर्गीकरण/नियम नोड पुन्हा गणना करते व अचूक अनुपालन फरक दाखवताते.',
    ta: 'விளம்பரக் கூற்றுகள் அல்லது கலவை அளவுருக்களை நேரடியாக மாற்றுங்கள். செயல்பாட்டு சார்பு DAG பாதிக்கப்பட்ட வகைப்பாட்டு/விதி கணுக்களை மட்டுமே மீண்டும் கணக்கிட்டு துல்லியமான இணக்க வேறுபாட்டைக் காட்டுகிறது.',
    te: 'ప్రచార దావనాలు లేదా సూత్రీకరణ పరిమాణాలను లైవ్‌గా మార్చండి. రియాక్టివ్ ఆధారిత DAG ప్రభావిత వర్గీకరణ/నియమ నోడ్‌లను మాత్రమే మళ్లీ లెక్కిస్తుంది, ఖచ్చితమైన సంపామిత తేడా హైలైట్ చేస్తుంది.',
    kn: 'ಜಾಹೀರಾತು ಹೇಳಿಕೆ ಅಥವಾ ಸೂತ್ರೀಕರಣ ಪ್ರಮಾಣಗಳನ್ನು ನೇರವಾಗಿ ಬದಲಿಸಿ. ಪ್ರತಿಕ್ರಿಯಾ ಆಶ್ರಯ DAG ಪೀಡಿತ ವರ್ಗೀಕರಣ/ನಿಯಮ ಘಟಕಗಳನ್ನು ಮಾತ್ರ ಪುನರ್ಗಣಿಸಿ ನಿಖರ ಅನುಸರಣ ವ್ಯತ್ಯಾಸವನ್ನು ಒತ್ತಿಸುತ್ತದೆ.',
    bn: 'প্রচার দাবি বা ফর্মুলেশন প্যারামিটার লাইভ পরিবর্তন করুন। রিঅ্যাকটিভ নির্ভরতা DAG কেবল প্রভাবিত শ্রেণীবিভাগ/নিয়ম নোড পুনরায় গণনা করে এবং সঠিক সম্মতি-পার্থক্য হাইলাইট করে।',
    gu: 'જાહેરાત દાવઓ અથવા ફોર્મ્યુલેશન પેરામીટર લાઇવ બદલો. રિએક્ટિવ આધારિત DAG ફક્ત અસરગ્રસ્ત વર્ગીકરણ/નિયમ નોડ્સની ફરી ગણતરી કરે છે અને ચોકસાઈથી અનુપાલન તફાવત દર્શાવે છે.',
    ml: 'പ്രചാര അവകാശങ്ങളോ ഫോർമുലേഷൻ പാരാമീടറോ ലൈവായി മാറ്റുക. റിയാക്ടീവ് ആശ്രയ DAG ബാധിത വർഗ്ഗീകരണ/നിയമ നോഡുകൾ മാത്രം പുനഃകണക്കാക്കി കൃത്യമായ പാലന വ്യത്യാസം സമ്മാഹിപ്പിക്കുന്നു.',
    sa: 'प्रचार-दावा अथवा सूत्रीकरण-पैरामीटराणि सद्यम् परिवर्तयतु। प्रतिक्रियाशील-आश्रय-DAG केवलम् अभिभावित-वर्गीकरण-नियम-घटकान् पुनर्गणयति सटीकानुसारण-भेदं च दर्शयति।',
  },
