    mr: '\n\nअद्यापर्यंत पासपोर्ट तयार केलेला नाही — Overview पानावरील "Create a New Innovation Passport" पासून सुरुवात करा.',
    ta: '\n\nஇதுவரை பாஸ்போர்ட் உருவாக்கப்படவில்லை — Overview பக்கத்தில் "Create a New Innovation Passport" என்பதிலிருந்து தொடங்குங்கள்.',
    te: '\n\nఇంకా పాస్‌పోర్ట్ సృష్టించలేదు — Overview పేజీలో "Create a New Innovation Passport" నుంచి ప్రారంభించండి.',
    kn: '\n\nಇನ್ನೂ ಪಾಸ್‌ಪೋರ್ಟ್ ರಚಿಸಲಾಗಿಲ್ಲ — Overview ಪುಟದ "Create a New Innovation Passport" ನಿಂದ ಪ್ರಾರಂಭಿಸಿ.',
    bn: '\n\nএখনও কোনো পাসপোর্ট তৈরি হয়নি — Overview পেজের "Create a New Innovation Passport" থেকে শুরু করুন।',
    gu: '\n\nહજી કોઈ પાસપોર્ટ બન્યો નથી — Overview પાનાના "Create a New Innovation Passport" થી શરૂ કરો.',
